create extension if not exists pgcrypto;
create table if not exists public.games(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,genre text not null,developer text not null,platforms text[] not null default '{}',cover_path text not null,summary text not null,release_year integer,editorial_score numeric(3,1) check(editorial_score is null or editorial_score between 0 and 10),featured boolean not null default false,long_description text,gameplay text,player_mode text,tags text[] not null default '{}',official_url text,created_at timestamptz not null default now());
alter table public.games add column if not exists long_description text,add column if not exists gameplay text,add column if not exists player_mode text,add column if not exists tags text[] not null default '{}',add column if not exists official_url text;
create table if not exists public.reviews(id uuid primary key default gen_random_uuid(),game_id uuid not null references public.games(id) on delete cascade,title text not null,excerpt text not null,score numeric(3,1) not null check(score between 0 and 10),published_at timestamptz not null default now(),unique(game_id));
create table if not exists public.articles(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,category text not null,excerpt text not null,cover_path text not null,reading_minutes integer not null default 4 check(reading_minutes between 1 and 60),published_at timestamptz not null default now());
create index if not exists games_featured_title_idx on public.games(featured desc,title);create index if not exists games_genre_idx on public.games(genre);create index if not exists reviews_published_idx on public.reviews(published_at desc);create index if not exists articles_published_idx on public.articles(published_at desc);
alter table public.games enable row level security;alter table public.reviews enable row level security;alter table public.articles enable row level security;
drop policy if exists "Public can read games" on public.games;create policy "Public can read games" on public.games for select to anon,authenticated using(true);
drop policy if exists "Public can read reviews" on public.reviews;create policy "Public can read reviews" on public.reviews for select to anon,authenticated using(true);
drop policy if exists "Public can read articles" on public.articles;create policy "Public can read articles" on public.articles for select to anon,authenticated using(true);
grant usage on schema public to anon,authenticated;grant select on public.games,public.reviews,public.articles to anon,authenticated;